#include <iostream>
#include <fstream>
class FileOpener {
public:
  FileOpener(const std::string& filename) : file_(filename) {
    if (!file_) {
      throw std::runtime_error("Could not open file");
    }
  }
  ~FileOpener() {
    // Always close the file, even if an exception occurred earlier
    file_.close();
  }
  std::ofstream& getFile() { return file_; }
private:
  std::ofstream file_;
};
int main() {
  try {
    FileOpener myFile("example.txt");
    myFile.getFile() << "Hello, world!\n";
  } catch (const std::runtime_error& error) {
    std::cerr << "Error: " << error.what() << std::endl;
  }
  return 0;
}
